SELECT analytics_order_facts.category, COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 11 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' GROUP BY analytics_order_facts.category ORDER BY active_customer_count DESC, analytics_order_facts.category ASC LIMIT 12
